import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, Chip, Regla, Contador, Ondas, Destello, golpe, sacudida, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const GANO = en('ganó'), CARRO1 = en('carro'), FUE = en('Fue'), TREINTA = en('treinta'), LOS = en('Los'), POLVO = en('polvo'), RESP = en('respiraban');
const FRED = en('Fred'), ACALAM = en('acalambró'), QUINCE = en('quince'), SUBIO = en('subió'), CARRO2 = en('carro', 2), VIAJO = en('Viajó'), SALUD = en('saludando');
const CERCA = en('Cerca'), CARRO3 = en('carro', 3), DANO = en('dañó'), BAJO = en('bajó'), FRESCO = en('fresco'), ENTRO = en('Entró'), ESTADIO = en('estadio');
const PRIMERO = en('primero'), CAMPEON = en('campeón'), HASTA = en('Hasta'), FOTO = en('foto'), PRESID = en('presidente'), MINUTOS = en('Minutos'), CARRO4 = en('carro', 4);
const BROMA = en('broma'), DESCAL = en('descalificaron'), ORO = en('oro'), HICKS = en('Hicks'), DESMAY = en('desmayado'), SU = en('Su'), CLARA = en('clara');
const BRANDY = en('brandy'), ESTRIC = en('estricnina'), RATAS = en('ratas'), EPOCA = en('época'), MATA = en('mata'), GANO2 = en('Ganó', 2), TRES = en('tres');
const LENTAS = en('lentas'), DESDE = en('Desde'), VIGILA = en('vigila'), FIN = en('fin'), DALE = en('Dale'), ATAJO = en('atajo');

const LIMA = '#E7FF00', OCRE = '#D9B36C', OCRE2 = '#8A6A3A', PIEL = '#E3B08A';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;
const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 4200}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

// ---------- piezas dibujadas ----------
// Corredor de 1904: pies en (x,y). ph = fase de la zancada; mitad = solo de la cintura para arriba (sentado en el carro)
const Corredor: React.FC<{x: number; y: number; sc?: number; ph?: number; dorsal?: string; flip?: boolean; camisa?: string; pelo?: string; piel?: string; tos?: number; sudor?: number; saluda?: number; mitad?: boolean; palido?: number; brazosArriba?: number; calambre?: number}> = ({
  x, y, sc = 1, ph = 0, dorsal = '31', flip, camisa = '#F4F1E8', pelo = '#3A2A1E', piel = PIEL, tos = 0, sudor = 0, saluda = 0, mitad, palido = 0, brazosArriba = 0, calambre = 0,
}) => {
  const a = Math.sin(ph) * 34 * (1 - calambre);
  const pc = palido > 0 ? '#B8C99A' : piel;
  return (
    <g transform={`translate(${x} ${y}) scale(${flip ? -sc : sc} ${sc})`}>
      {!mitad && <ellipse cx={0} cy={4} rx={80} ry={14} fill="rgba(60,40,10,0.35)" />}
      {!mitad && [1, -1].map((k) => (
        <g key={k} transform={`translate(0 -150) rotate(${a * k + (k < 0 ? calambre * 28 : 0)})`}>
          <rect x={-15} y={0} width={30} height={84} rx={14} fill={pc} stroke="#8A6040" strokeWidth={3} />
          <g transform={`translate(0 80) rotate(${Math.max(0, -a * k) * 1.1 + (k < 0 ? calambre * 50 : 0)})`}>
            <rect x={-13} y={0} width={26} height={78} rx={12} fill={pc} stroke="#8A6040" strokeWidth={3} />
            <ellipse cx={8} cy={80} rx={26} ry={11} fill="#3A2A1E" />
          </g>
        </g>
      ))}
      {!mitad && <rect x={-48} y={-176} width={96} height={52} rx={14} fill="#2B2F45" />}
      <rect x={-46} y={-304} width={92} height={166} rx={26} fill={camisa} stroke="#B8B2A0" strokeWidth={4} />
      <rect x={-22} y={-302} width={44} height={20} rx={10} fill={pc} />
      <g transform="translate(0 -236)">
        <rect x={-30} y={-24} width={60} height={46} rx={4} fill="#fff" stroke="#6A6A6A" strokeWidth={3} />
        <text x={0} y={10} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={800} fontSize={34} fill="#222">{dorsal}</text>
        {[[-30, -24], [30, -24], [-30, 22], [30, 22]].map(([px, py], i) => <circle key={i} cx={px} cy={py} r={3} fill="#999" />)}
      </g>
      {[1, -1].map((k) => {
        const ang = k > 0 ? (saluda ? -130 + Math.sin(ph * 2) * 22 : -a * 0.8 - brazosArriba * 150) : a * 0.8 - brazosArriba * 150;
        return (
          <g key={k} transform={`translate(${46 * k} -288) rotate(${ang})`}>
            <rect x={-11} y={0} width={22} height={112} rx={11} fill={pc} stroke="#8A6040" strokeWidth={3} />
            <circle cx={0} cy={116} r={14} fill={pc} stroke="#8A6040" strokeWidth={3} />
          </g>
        );
      })}
      <circle cx={0} cy={-346} r={42} fill={pc} stroke="#8A6040" strokeWidth={3} />
      <path d={`M -40 -356 C -40 -400 40 -400 40 -356 C 20 -378 -20 -378 -40 -356 Z`} fill={pelo} />
      <path d="M -22 -330 Q 0 -340 22 -330 Q 0 -322 -22 -330 Z" fill={pelo} />
      <circle cx={-14} cy={-352} r={4} fill="#222" /><circle cx={14} cy={-352} r={4} fill="#222" />
      {tos > 0 ? <ellipse cx={0} cy={-322} rx={13} ry={9} fill="#7A2A2A" /> : <path d="M -12 -318 Q 0 -310 12 -318" stroke="#7A2A2A" strokeWidth={4} fill="none" />}
      {tos > 0 && <g transform={`translate(${2 + Math.sin(ph * 4) * 3} -318)`}><circle r={17} fill={pc} stroke="#8A6040" strokeWidth={3} /></g>}
      {sudor > 0 && [-28, 30].map((dx, i) => <path key={i} d={`M ${dx} -380 q 6 14 0 20 q -8 -6 0 -20 Z`} fill="#8FD3F5" opacity={0.9 * sudor} />)}
    </g>
  );
};

// Carro antiguo negro de 1904 (mira a la derecha)
const Carro: React.FC<{x: number; y: number; sc?: number; flip?: boolean; humo?: number; puerta?: number; rebote?: number; bocina?: number}> = ({x, y, sc = 1, flip, humo = 0, puerta = 0, rebote = 0, bocina = 0}) => {
  const {s} = useS();
  return (
    <g transform={`translate(${x} ${y + rebote}) scale(${flip ? -sc : sc} ${sc})`}>
      <ellipse cx={0} cy={4} rx={230} ry={18} fill="rgba(40,30,10,0.4)" />
      <path d="M -220 -60 L -220 -150 L -80 -150 L -60 -250 L 70 -250 L 90 -150 L 220 -150 L 220 -60 Z" fill="#1A1A1E" stroke="#000" strokeWidth={5} />
      <path d="M -60 -246 L 66 -246 L 82 -156 L -72 -156 Z" fill="#7E6B4C" opacity={0.0} />
      <rect x={-60} y={-250} width={130} height={14} rx={6} fill="#3A3A42" />
      <path d="M -200 -140 L 200 -140" stroke="#C9A23F" strokeWidth={6} />
      <path d={`M -2 -148 L -2 -66 L ${-2 + 60 * puerta} ${-70 - 10 * puerta} L ${-2 + 60 * puerta} ${-150 + 10 * puerta} Z`} fill="#2A2A30" stroke="#000" strokeWidth={4} opacity={puerta > 0 ? 1 : 0} />
      {[[-130, -20], [140, -20]].map(([wx, wy], i) => (
        <g key={i} transform={`translate(${wx} ${wy}) rotate(${s * 220})`}>
          <circle r={62} fill="#2A2A2A" stroke="#000" strokeWidth={5} />
          <circle r={38} fill="#C9A23F" stroke="#8A6A20" strokeWidth={4} />
          {[0, 1, 2, 3, 4, 5].map((k) => <line key={k} x1={0} y1={0} x2={Math.cos((k / 6) * Math.PI * 2) * 38} y2={Math.sin((k / 6) * Math.PI * 2) * 38} stroke="#8A6A20" strokeWidth={4} />)}
        </g>
      ))}
      <circle cx={214} cy={-110} r={20} fill="#F2D77A" stroke="#8A6A20" strokeWidth={4} />
      <g transform={`translate(236 -170) scale(${1 + 0.35 * bocina})`}><path d="M 0 0 L 40 -22 L 40 22 Z" fill="#C9A23F" stroke="#8A6A20" strokeWidth={3} /><circle cx={-8} cy={0} r={10} fill="#222" /></g>
      {bocina > 0.05 && [0, 1, 2].map((i) => <path key={i} d={`M ${290 + i * 34} ${-210 - i * 12} q 22 40 0 80`} stroke={LIMA} strokeWidth={9} fill="none" strokeLinecap="round" opacity={bocina} />)}
      {humo > 0 && Array.from({length: 7}).map((_, i) => {
        const k = ((s * 0.9 + i / 7) % 1);
        return <circle key={i} cx={-150 - 10 * i + Math.sin(k * 6 + i) * 20} cy={-210 - k * 220} r={30 + k * 50} fill="#555" opacity={humo * (1 - k) * 0.8} />;
      })}
    </g>
  );
};

const Polvo: React.FC<{x: number; y: number; n?: number; r?: number; op?: number; t0?: number}> = ({x, y, n = 8, r = 60, op = 0.6, t0 = 0}) => {
  const {s} = useS();
  return (
    <g opacity={op}>
      {Array.from({length: n}).map((_, i) => {
        const k = (((s - t0) * 0.45 + i / n) % 1 + 1) % 1;
        return <ellipse key={i} cx={x - k * 320 + Math.sin(i * 3 + s) * 10} cy={y - 30 - k * 140 - h(i) * 40} rx={r * (0.6 + k * 1.1)} ry={r * (0.45 + k * 0.7)} fill={i % 2 ? '#E8D29A' : '#D4B67A'} opacity={(1 - k) * 0.85} />;
      })}
    </g>
  );
};

const Cielo: React.FC<{y1?: number; col?: string[]}> = ({y1 = 1100, col = ['#F2DDA4', '#E6C07A', '#C99A52']}) => (
  <>
    <defs><linearGradient id="cieloG" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={col[0]} /><stop offset="60%" stopColor={col[1]} /><stop offset="100%" stopColor={col[2]} /></linearGradient></defs>
    <rect x={-600} y={0} width={4200} height={y1} fill="url(#cieloG)" />
  </>
);

// ---------- Sitio 1: meta del estadio, el corredor, la cinta y el carro detrás (E1) ----------
const Gradas: React.FC<{lleno?: number}> = ({lleno = 1}) => (
  <g>
    <rect x={-600} y={420} width={4200} height={680} fill="#7A2A2A" />
    {[0, 1, 2, 3].map((i) => <rect key={i} x={-600} y={470 + i * 150} width={4200} height={70} fill={i % 2 ? '#F2F2F2' : '#B53A3A'} />)}
    {Array.from({length: 110}).map((_, i) => {
      const r = Math.floor(i / 27);
      return <g key={i}><circle cx={-560 + (i % 27) * 130 + (r % 2) * 40} cy={520 + r * 150 + Math.sin(i) * 8} r={26} fill={['#3A5A8A', '#D9B36C', '#E8E0D0', '#2B2F45', '#9A3A3A'][i % 5]} opacity={lleno} /></g>;
    })}
  </g>
);
const Meta: React.FC = () => {
  const {s, lin} = useS();
  const rom = lin(GANO, GANO + 0.35, 0, 1);
  const bo = lin(CARRO1 - 0.1, CARRO1 + 0.2, 0, 1) * (1 - lin(CARRO1 + 0.5, CARRO1 + 0.9, 0, 1));
  return (
    <AbsoluteFill style={{background: '#3A1A14'}}>
      <Camara paradas={[{t: 0, x: 520, y: 1100, zoom: 1.0}, {t: GANO, x: 560, y: 1040, zoom: 1.25}, {t: CARRO1 + 0.5, x: 470, y: 1060, zoom: 1.5}]}>
        <Mundo>
          <Cielo y1={420} />
          <Gradas />
          <rect x={-600} y={1100} width={4200} height={820} fill={OCRE} />
          {[0, 1, 2].map((i) => <rect key={i} x={-600} y={1180 + i * 130} width={4200} height={10} fill="#fff" opacity={0.5} />)}
          <Polvo x={330} y={1380} n={9} r={80} op={0.85} />
          <Carro x={180} y={1420} sc={0.6} rebote={Math.sin(s * 14) * 3} bocina={bo} />
          {/* cinta de meta */}
          <rect x={806} y={1080} width={14} height={360} fill="#555" /><rect x={236} y={1080} width={14} height={360} fill="#555" />
          <path d={`M 243 1160 L ${243 + (1 - rom) * 570} ${1160 + rom * 60}`} stroke="#E83A3A" strokeWidth={14} />
          <path d={`M 813 1160 L ${813 - rom * 140} ${1160 + rom * 220 + 60 * rom}`} stroke="#E83A3A" strokeWidth={14} />
          <Corredor x={600 + Math.min(1, s / GANO) * 120} y={1440} sc={1.9} ph={s * 11} dorsal="31" sudor={0.0} />
        </Mundo>
        <Ondas x={820} y={1200} t0={GANO} color="#fff" radio={300} />
        <Ondas x={420} y={1240} t0={CARRO1} color={LIMA} radio={260} />
      </Camara>
      <Destello t0={GANO} fuerza={0.25} />
    </AbsoluteFill>
  );
};

// ---------- Sitio 2: mapa, sol enorme y termómetro (E2) ----------
const Mapa: React.FC = () => {
  const {s, lin, spr} = useS();
  const sube = lin(TREINTA - 0.6, TREINTA + 0.3, 0, 1, Easing.out(Easing.cubic));
  return (
    <AbsoluteFill style={{background: '#4A3A1E'}}>
      <Camara paradas={[{t: FUE - 0.3, x: 540, y: 1100, zoom: 1.0}, {t: TREINTA, x: 480, y: 1050, zoom: 1.2}, {t: LOS - 0.2, x: 600, y: 1180, zoom: 1.45}]}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 55%, #F3E1B2, #D9B36C 70%, #8A6A3A)" linea="rgba(110,70,20,0.5)" luz="rgba(255,240,200,0.3)" semilla={3} />
        <Lienzo>
          <path d="M 120 1000 C 160 900 330 880 520 900 C 700 880 880 900 960 960 C 1000 1040 960 1160 880 1220 C 800 1300 640 1360 520 1340 C 400 1360 260 1300 200 1220 C 120 1160 90 1080 120 1000 Z" fill="#CBA766" stroke={OCRE2} strokeWidth={8} />
          <path d="M 200 1000 C 380 960 600 1010 900 980" stroke={OCRE2} strokeWidth={4} fill="none" strokeDasharray="14 12" opacity={0.6} />
          {/* sol enorme */}
          <g transform={`translate(800 600) rotate(${s * 8})`}>
            {Array.from({length: 16}).map((_, i) => <path key={i} d={`M 0 -190 L 20 -260 L -20 -260 Z`} fill="#FFB02E" transform={`rotate(${i * 22.5})`} opacity={0.9} />)}
            <circle r={170} fill="#FF8A2A" stroke="#C2570E" strokeWidth={8} /><circle r={120} fill="#FFC857" opacity={0.7} />
          </g>
          {/* marcador de San Luis */}
          <g transform={`translate(560 1130) scale(${spr(FUE + 0.3, 10, 160)})`}>
            <circle r={44} fill="none" stroke={LIMA} strokeWidth={8} opacity={0.8} />
            <path d="M 0 0 C -30 -50 -30 -90 0 -100 C 30 -90 30 -50 0 0 Z" fill="#D63A3A" stroke="#7A1414" strokeWidth={5} transform="translate(0 -20)" />
            <circle cx={0} cy={-100} r={10} fill="#fff" />
          </g>
          {/* termómetro antiguo */}
          <g transform="translate(190 1040)">
            <rect x={-30} y={0} width={60} height={440} rx={30} fill="#F2EAD6" stroke="#7A5A28" strokeWidth={6} />
            <circle cx={0} cy={470} r={52} fill="#E83A3A" stroke="#7A5A28" strokeWidth={6} />
            <rect x={-14} y={440 - 400 * sube} width={28} height={30 + 400 * sube} rx={14} fill="#E83A3A" />
            {[0, 1, 2, 3, 4, 5].map((i) => <line key={i} x1={30} y1={40 + i * 70} x2={52} y2={40 + i * 70} stroke="#7A5A28" strokeWidth={4} />)}
          </g>
          {Array.from({length: 5}).map((_, i) => <path key={i} d={`M ${330 + i * 120} ${900 - Math.sin(s * 4 + i) * 6} q 14 -20 0 -40 q -14 -20 0 -40`} stroke="#D6541A" strokeWidth={5} fill="none" opacity={0.45} />)}
        </Lienzo>
        <Brillo x={800} y={600} r={420} color="rgba(255,160,40,0.5)" />
        <Chip texto="1904" x={540} y={470} t0={FUE} t1={LOS} size={84} />
        <Chip texto="30 grados" x={430} y={900} t0={TREINTA} t1={LOS} size={52} color="#FF8A2A" />
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 3: camino de tierra, jueces, calambre, carro y avería (E3-E6) ----------
const fredCorre = (s: number) => interpolate(s, [LOS, ACALAM, SUBIO], [400, 880, 905], clamp);
const carroX = (s: number) => interpolate(s, [ACALAM, CARRO2 - 0.4, VIAJO, DANO, 99], [250, 1040, 1040, 2000, 2000], {...clamp, easing: Easing.inOut(Easing.quad)});
const Camino: React.FC = () => {
  const {s, lin, spr} = useS();
  const board = lin(SUBIO, CARRO2 + 0.1, 0, 1);
  const rodando = s > VIAJO && s < DANO;
  let fx = fredCorre(s) * (1 - board) + (carroX(s) + 10) * board;
  const baja = lin(BAJO, FRESCO, 0, 1);
  if (s > BAJO) fx = carroX(s) + 10 + baja * 400 + Math.max(0, s - FRESCO) * 150;
  const sentado = s > SUBIO + 0.2 && s < BAJO;
  const fy = 1480 - (sentado ? 20 : 0);
  const trota = s > BAJO + 0.5;
  const pasoJ = (i: number) => 1060 + i * 460 + (s - LOS) * 72;
  const corredoresX = [150 + 60 * (s - LOS) * 0.9, 700 + 50 * (s - LOS), 520 + 62 * (s - LOS)];
  const cam: {t: number; x: number; y: number; zoom: number}[] = [];
  for (let t = LOS; t <= FRESCO + 1.2; t += 0.5) {
    const x = (() => {
      const b = Math.max(0, Math.min(1, (t - SUBIO) / (CARRO2 + 0.1 - SUBIO)));
      let f = interpolate(t, [LOS, ACALAM, SUBIO], [400, 880, 905], clamp) * (1 - b) + (carroX(t) + 10) * b;
      if (t > BAJO) f = carroX(t) + 10 + Math.max(0, Math.min(1, (t - BAJO) / (FRESCO - BAJO))) * 400 + Math.max(0, t - FRESCO) * 150;
      return f;
    })();
    const z = t < POLVO ? 1.0 : t < RESP ? 1.25 : t < ACALAM + 0.8 ? 1.0 : t < QUINCE + 1 ? 1.55 : t < SALUD ? 1.1 : t < CERCA ? 1.3 : t < BAJO - 0.5 ? 1.0 : 1.35;
    cam.push({t, x: x + (t < ACALAM ? 260 : 120), y: 1260, zoom: z});
  }
  const flexL = s > ACALAM && s < SUBIO ? 1 : 0;
  return (
    <AbsoluteFill style={{background: '#C49A52'}}>
      <Camara paradas={cam} centroY={1100}>
        <Mundo w={5200}>
          <Cielo y1={1080} col={['#F4E2B0', '#E8C888', '#D4A862']} />
          <path d="M -600 1080 C -200 900 200 1000 600 920 C 1100 860 1600 1010 2200 930 C 2800 880 3300 1000 4000 940 L 4000 1100 L -600 1100 Z" fill="#B58A4A" opacity={0.7} />
          <rect x={-600} y={1070} width={5200} height={850} fill={OCRE} />
          <rect x={-600} y={1250} width={5200} height={300} fill="#C49A52" />
          {Array.from({length: 22}).map((_, i) => <g key={i}><rect x={-400 + i * 260} y={1130} width={12} height={90 + h(i) * 30} fill="#6A4A22" /><ellipse cx={-380 + i * 260 + 40} cy={1580 + h(i + 3) * 200} rx={18 + h(i) * 14} ry={9} fill={OCRE2} opacity={0.55} /></g>)}
          {Array.from({length: 26}).map((_, i) => <rect key={'d' + i} x={-500 + i * 210} y={1400} width={110} height={10} fill="#E8D29A" opacity={0.7} />)}
          {/* jueces adelante levantando polvo */}
          {[0, 1].map((i) => <g key={i}><Polvo x={pasoJ(i) - 60} y={1360} n={9} r={90} op={0.9} /><Carro x={pasoJ(i)} y={1380} sc={0.55} rebote={Math.sin(s * 12 + i) * 3} /></g>)}
          {/* corredores que tosen */}
          {corredoresX.map((cx, i) => <Corredor key={i} x={cx} y={1440 + (i - 1) * 25} sc={0.78} ph={s * 8 + i * 2} dorsal={['12', '27', '8'][i]} tos={s > POLVO && s < ACALAM ? 1 : 0} sudor={s > RESP ? 0.8 : 0} piel={['#D9A67E', '#B8825C', '#E3B08A'][i]} camisa={['#EDE6D2', '#F4F1E8', '#E4E8F0'][i]} />)}
          <Corredor x={fx} y={fy} sc={0.88} ph={sentado ? s * 3 : trota ? s * 9 : s * 8} dorsal="31" mitad={sentado && s > CARRO2 + 0.3} calambre={flexL} saluda={s > VIAJO && s < DANO ? 1 : 0} tos={s > POLVO && s < RESP + 0.5 ? 1 : 0} sudor={s < ACALAM ? 0.7 : s > BAJO ? 0 : 0.2} />
          <Carro x={carroX(s)} y={1470} sc={0.74} puerta={lin(CARRO2 - 0.6, CARRO2, 0, 1) * (1 - lin(VIAJO, VIAJO + 0.3, 0, 1))} rebote={rodando ? Math.sin(s * 16) * 4 : 0} humo={s > DANO - 0.3 ? 1 : 0} />
          {s > CARRO2 + 0.3 && s < BAJO && <rect x={carroX(s) - 90} y={1210} width={170} height={30} fill="none" />}
        </Mundo>
        <Chip texto="km 15" x={fredCorre(s) + 140} y={1020} t0={QUINCE} t1={SUBIO + 0.6} size={72} />
        <Ondas x={fredCorre(ACALAM + 0.4) + 10} y={1360} t0={ACALAM} color="#F2A0A0" radio={240} />
        <Ondas x={carroX(DANO) + 20} y={1300} t0={DANO} color="#aaa" radio={260} />
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 4: estadio lleno, la foto y el juez (E7-E9) ----------
const Estadio: React.FC = () => {
  const {s, lin, spr} = useS();
  const corre = lin(ENTRO, PRIMERO, 0, 1);
  const fx = interpolate(s, [ENTRO, PRIMERO, HASTA, FOTO], [-100, 620, 520, 520], clamp);
  const flash = Math.max(0, 1 - Math.abs(s - FOTO - 0.5) * 6);
  const tachado = lin(DESCAL, DESCAL + 0.35, 0, 1);
  const rom = lin(PRIMERO - 0.5, PRIMERO - 0.1, 0, 1);
